using System.Windows.Forms;

public class MainForm : Form
{
    private StatusStrip statusStrip;

    public MainForm()
    {
        statusStrip = new StatusStrip();

        // .NET 9 breaking change: StatusStrip/ToolStrip default RenderMode changed.
        // Explicitly set the renderer to preserve .NET 8 visual appearance.
        statusStrip.RenderMode = ToolStripRenderMode.Professional;

        statusStrip.Items.Add(new ToolStripStatusLabel("Ready"));
        Controls.Add(statusStrip);
    }
}

using System;
using System.Drawing.Design;
using System.Windows.Forms;
using System.Windows.Forms.Design;

public class MyDropDownEditor : UITypeEditor
{
    public override object EditValue(
        System.ComponentModel.ITypeDescriptorContext context,
        IServiceProvider provider,
        object value)
    {
        var editorService = provider?.GetService(typeof(IWindowsFormsEditorService))
            as IWindowsFormsEditorService;

        if (editorService == null)
            return value;

        var control = CreateEditorControl(value);

        // .NET 9 breaking change: DropDownControl now throws ArgumentNullException
        // if passed null. Guard against null before calling.
        if (control != null)
        {
            editorService.DropDownControl(control);
            value = GetValueFromControl(control);
        }

        return value;
    }

    private Control? CreateEditorControl(object value)
    {
        // May return null in some scenarios (e.g., no valid choices available)
        var listBox = new ListBox();
        listBox.Items.Add(value ?? "(none)");
        return listBox;
    }

    private object GetValueFromControl(Control control)
    {
        if (control is ListBox lb && lb.SelectedItem != null)
            return lb.SelectedItem;
        return string.Empty;
    }

    public override UITypeEditorEditStyle GetEditStyle(
        System.ComponentModel.ITypeDescriptorContext context)
    {
        return UITypeEditorEditStyle.DropDown;
    }
}

